insert into auth.identities(id,user_id,identity_data,provider,provider_id,last_sign_in_at,created_at,updated_at) select id,id,jsonb_build_object('sub',id,'email',email),'email',id::text,now(),now(),now() from auth.users where id::text like '10000000-%' or id::text like '20000000-%' on conflict(provider_id,provider) do nothing;
